WITH with_windows AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY device ORDER BY started_at DESC, id) AS seq_no, LAST_VALUE(country) IGNORE NULLS OVER w_grp AS last_known_country, LAST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser FROM sessions WINDOW w_grp AS (PARTITION BY customer_id, country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT seq_no, CASE WHEN seq_no >= 8 THEN 'LARGE' ELSE 'SMALL' END AS seq_no_tier, ROUND(SUM(seq_no) / NULLIF(COUNT(CASE WHEN device = 'desktop' THEN 1 END), 0), 2) AS seq_no_per_desktop, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, COUNT(*) AS cnt FROM with_windows GROUP BY seq_no, seq_no_tier
